#include <mutex>
#include <chrono>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::mutex mutex;
    mutex.lock();
    mutex.unlock();
    assert(mutex.try_lock());
    mutex.unlock();

    // native_handle is implementation-defined and is not required for shared_mutex.
    auto native = mutex.native_handle();
    (void)native;
}
